<script lang="ts">
 import{api,percent,number,stamp,updatedStamp,compact,cost,iconPath,type Row}from'../lib/api';import{tr}from'../lib/i18n';import Icon from './Icon.svelte';
 export let settings:Row={};export let quota:Row={};export let summary:Row={};export let preview=false;export let onsave:(r:Row)=>Promise<void>=async()=>{};export let onerror:(e:any)=>void=()=>{};
 let context:{x:number,y:number}|null=null;let contextElement:HTMLDivElement;let refreshing=false;
 function remaining(w:Row){return number(w?.remaining_percent)??(number(w?.used_percent)===null?null:100-Number(w.used_percent))}
 function quotaColor(n:number|null){return n===null?'#D0D5DD':n>=50?'#7DDEA0':n>=20?'#F6D56B':'#FF8A80'}
 function label(n:number|null){return n===null?'N/A':`${Math.round(n)}%`}
 async function action(name:string){context=null;try{await api('DesktopAction',name)}catch(e){onerror(e)}}
 async function refresh(){if(refreshing||preview)return;refreshing=true;context=null;try{await api('Refresh')}catch(e){onerror(e)}finally{refreshing=false}}
 function menu(event:MouseEvent){if(preview)return;event.preventDefault();context={x:Math.max(4,Math.min(event.clientX,innerWidth-156)),y:Math.max(4,Math.min(event.clientY,innerHeight-154))}}
 function outside(event:PointerEvent){if(context&&!contextElement?.contains(event.target as Node))context=null}
 $: style=settings.visual_style??'classic';$: scope=settings.quota_scope??'auto';
 $: windows=scope==='week'||scope==='auto'&&remaining(quota.primary??{})===null?[['周额度',quota.secondary??{}]]:[['5 小时额度',quota.primary??{}],['周额度',quota.secondary??{}]];
 $: orb=windows[0];$: orbRemaining=remaining(orb?.[1]??{});$: waterY=100-Math.max(10,Math.min(88,orbRemaining??0));
 $: background=settings.background_transparent?`rgba(27,27,31,${(100-Number(settings.background_opacity??70))/100})`:'rgb(27,27,31)';
 $: status=quota.error??(quota.updated_at?(tr('上次更新：')+updatedStamp(quota.updated_at)):quota.status==='reading'?tr('正在读取'):quota.status==='stale'?tr('数据过期'):'');
</script>
<svelte:window onpointerdown={outside} onkeydown={event=>{if(event.key==='Escape')context=null}}/>
<div class={`floating python-floating ${style}`} class:preview class:docked={!preview&&settings.dock_edge&&settings.dock_edge!=='none'} class:vertical={!preview&&['left','right'].includes(settings.dock_edge)} style:background={style==='orb'&&!settings.dock_edge?'transparent':background} style:border-color={settings.show_border===false?'transparent':settings.border_color??'#8AB4F8'} style="--wails-draggable:drag" oncontextmenu={menu} ondblclick={()=>action('show-main')} role="presentation">
 {#if !preview&&settings.dock_edge&&settings.dock_edge!=='none'}
 <button class="quiet dock-brand" aria-label={tr('打开主窗口')} onclick={()=>action('show-main')}><img src={iconPath(settings.app_icon??'main')} alt="Codexio"/></button>{#each windows as [title,w]}{@const n=remaining(w)}<div class="dock-quota"><span>{title==='周额度'?tr('周'):tr('5 小时')}</span><strong style:color={quotaColor(n)}>{label(n)}</strong><div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`} style:background={quotaColor(n)}></div></div></div>{/each}<button class="quiet" onclick={refresh} disabled={refreshing} aria-label={tr('刷新')}><Icon name="refresh" size={13}/></button>
 {:else if style==='orb'}
 <div class="water-orb" title={`${tr(orb[0])} · ${label(orbRemaining)} · ${tr('重置')} ${stamp(orb[1].resets_at)}`}><svg viewBox="0 0 100 100" aria-label={`${tr(orb[0])} ${label(orbRemaining)}`}><defs><clipPath id={preview?'preview-orb-clip':'orb-clip'}><circle cx="50" cy="50" r="48"/></clipPath><radialGradient id={preview?'preview-cavity':'cavity'}><stop offset="0" stop-color="#3A4854"/><stop offset=".7" stop-color="#202A34"/><stop offset="1" stop-color="#141C24"/></radialGradient><linearGradient id={preview?'preview-water':'water'} x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7DF0B5"/><stop offset=".28" stop-color="#3DDC97"/><stop offset="1" stop-color="#1FA97A"/></linearGradient></defs><circle cx="50" cy="50" r="48" fill={`url(#${preview?'preview-cavity':'cavity'})`}/>{#if orbRemaining!==null}<g clip-path={`url(#${preview?'preview-orb-clip':'orb-clip'})`}><path class="orb-water" d={`M-20 ${waterY} Q5 ${waterY-6} 30 ${waterY} T80 ${waterY} T130 ${waterY} V104H-20Z`} fill={`url(#${preview?'preview-water':'water'})`}/></g>{/if}<circle cx="50" cy="50" r="47.5" fill="none" stroke="#E6F0F632" stroke-width="1.3"/><path d="M23 26Q30 14 42 13" fill="none" stroke="#FFFFFF46" stroke-width="1.2"/><text x="50" y="56" text-anchor="middle" font-size="26" fill="#F8FFFC">{label(orbRemaining)}</text></svg>{#if summary.tokens!=null}<small>{compact(summary.tokens)}<br/>{cost(summary.usd)}</small>{/if}</div>
 {:else}
 {#if !preview&&style!=='minimal'}<div class="floating-brand"><span class="floating-grip" aria-hidden="true">⠿</span><img src={iconPath(settings.app_icon??'main')} alt=""/><span>Codexio</span><button class="quiet" disabled={refreshing} onclick={refresh}>{tr('刷新')}</button></div>{/if}
 <div class="floating-quotas">{#each windows as [title,w]}{@const n=remaining(w)}<div class="floating-quota" style={`--quota-color:${quotaColor(n)}`}>
 {#if style==='rings'}<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" fill="none" stroke="#FFFFFF2E" stroke-width="10"/><circle cx="50" cy="50" r="40" fill="none" stroke={quotaColor(n)} stroke-width="10" stroke-linecap="round" pathLength="100" stroke-dasharray={`${Math.max(0,Math.min(100,n??0))} 100`} transform="rotate(-90 50 50)"/><text x="50" y="58" text-anchor="middle" font-size="29" fill="#F0F0F3">{n===null?'N/A':Math.round(n)}</text></svg><span>{tr(title)}</span><small>{stamp(w.resets_at)}</small>
 {:else if style==='classic'}<div class="floating-row-head"><span>{tr(title)}</span><strong>{label(n)}</strong></div><div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`}></div></div><small>{tr('重置')} {stamp(w.resets_at)}</small>
 {:else}<strong>{label(n)}</strong><span>{tr(title)}</span>{#if style!=='minimal'}<small>{stamp(w.resets_at)}</small>{/if}{/if}
 </div>{/each}</div>
 {#if !preview&&style!=='minimal'}<div class="floating-status" class:error={!!quota.error}>{status}{#if !quota.error&&summary.tokens!=null}<span>{compact(summary.tokens)} Token {cost(summary.usd)}</span>{/if}</div>{/if}
 {/if}
</div>
{#if context}<div class="floating-context" bind:this={contextElement} style:left={`${context.x}px`} style:top={`${context.y}px`} role="menu"><button role="menuitem" onclick={()=>action('show-main')}>{tr('打开主窗口')}</button><button role="menuitem" onclick={refresh}>{tr('刷新')}</button>{#if settings.dock_edge&&settings.dock_edge!=='none'}<button role="menuitem" onclick={()=>{context=null;void onsave({dock_edge:'none'}).catch(onerror)}}>{tr('取消停靠')}</button>{/if}<hr/><button role="menuitem" onclick={()=>action('hide-floating')}>{tr('隐藏悬浮窗')}</button></div>{/if}
<style>
 .python-floating.floating{--text:#F0F0F3;--muted:#AFB0BA;--tokens:#7DDEA0;--raised:#FFFFFF30;--hover:#FFFFFF12;--control:#44444D;color:#F0F0F3;display:flex;flex-direction:column;gap:8px;overflow:hidden;padding:12px 14px;border-radius:18px;backdrop-filter:none;-webkit-backdrop-filter:none;font-size:14px;text-shadow:0 1px 3px #0006;line-height:1.25}
 .python-floating.floating.preview{width:320px;max-width:100%;height:160px;min-height:0;padding:16px;--wails-draggable:no-drag!important}.python-floating .floating-brand{font-size:17px;gap:4px;min-height:27px;padding:2px 4px 2px 6px;border-radius:8px;background:#FFFFFF12;flex-shrink:0}.python-floating .floating-brand img{width:18px;height:18px}.python-floating .floating-grip{width:10px;color:#C8CED6;font-size:15px}.python-floating button{--wails-draggable:no-drag;min-height:20px;color:#AECBFA;font-size:13px;padding:2px 4px;background:transparent;border:0}.python-floating .floating-brand button{margin-left:auto}.python-floating button:hover{color:#D2E3FC;background:#FFFFFF12}.python-floating .floating-quotas{display:flex;flex:1;min-height:0;gap:12px;margin:0;align-items:stretch;justify-content:space-around}.python-floating.classic .floating-quotas{flex-direction:column}.python-floating .floating-quota{min-height:0;display:flex;flex-direction:column;justify-content:center;gap:4px;flex:1;text-align:center}.python-floating.classic .floating-quota{text-align:left}.python-floating .floating-row-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.python-floating .floating-row-head>span{font-size:14px}.python-floating .floating-quota strong{font-size:32px;color:var(--quota-color);font-weight:400;line-height:1.15}.python-floating.classic .floating-quota strong{font-size:22px}.python-floating .floating-quota>span{font-size:14px;margin:0;color:#E8EAED}.python-floating .floating-quota small{font-size:12px;line-height:1.25;color:#AFB0BA}.python-floating.classic .floating-quota small{font-size:14px}.python-floating .meter{height:8px;flex-shrink:0;margin:0;border-radius:4px;background:#FFFFFF30}.python-floating .meter>div{background:var(--quota-color)}.python-floating .floating-quota svg{height:100%;max-height:120px;width:100%;margin:0 auto;min-height:50px}.python-floating .floating-status{font-size:10px;color:#AFB0BA;display:flex;align-items:center;justify-content:space-between;gap:8px;white-space:nowrap;overflow:hidden;flex-shrink:0;min-height:13px}.python-floating .floating-status>span{font-size:10px}.python-floating.tiles .floating-quota{background:#FFFFFF12;border:1px solid #FFFFFF24;border-radius:14px;padding:8px}.python-floating.compact .floating-quotas{gap:16px}.python-floating.compact .floating-quota strong{font-size:22px}.python-floating.minimal .floating-quotas{gap:0}.python-floating.minimal .floating-quota strong{font-size:32px}.python-floating.minimal .floating-quota>span{font-size:14px}.python-floating.orb{padding:0;border:0;border-radius:0;background:transparent!important;display:grid;place-items:center}.python-floating.orb.preview{width:148px;height:148px}.water-orb{width:min(100%,100vh);height:100%;max-width:100%;aspect-ratio:1;position:relative}.water-orb svg{height:100%;width:100%;display:block}.water-orb small{position:absolute;left:0;right:0;top:64%;text-align:center;font-size:10px;line-height:1.2;color:#F2FFF9}.orb-water{animation:water-wave 3s ease-in-out infinite;transform-origin:center}@keyframes water-wave{0%,100%{transform:translateX(0)}50%{transform:translateX(-10px)}}
 .python-floating.docked{flex-direction:row;padding:4px 8px;gap:12px;border-radius:0;border:0}.python-floating.docked .dock-brand img{width:18px;height:18px}.python-floating.docked .dock-quota{gap:6px}.python-floating.docked .dock-quota>strong{font-size:18px;min-width:42px;font-weight:400}.python-floating.docked .dock-quota>span{color:#E8EAED;font-size:11px}.python-floating.docked .dock-quota .meter{height:6px}.python-floating.docked.vertical{flex-direction:column;padding:8px 4px;gap:8px}.python-floating.docked.vertical .dock-quota>strong{font-size:14px;min-width:0}.python-floating.docked.vertical .dock-quota>span{font-size:9px}.python-floating.docked.vertical .meter{width:32px;height:4px}.floating-context{--wails-draggable:no-drag;position:fixed;z-index:80;min-width:148px;max-width:calc(100vw - 8px);background:#1B1B1F;border:1px solid #44444D;border-radius:8px;padding:5px;box-shadow:0 5px 18px #0006;color:#F0F0F3}.floating-context button{color:#F0F0F3;border:0;background:transparent;font-size:12px;justify-content:flex-start;width:100%;min-height:28px}.floating-context button:hover{background:#303035}.floating-context hr{margin:4px;border:0;border-top:1px solid #44444D}@media(prefers-reduced-motion:reduce){.orb-water{animation:none}}
</style>
